using Cosine.Api.WebApi.Dtos;
using Cosine.Core.Entities;
using Cosine.Infrastructure.Services;
using Riok.Mapperly.Abstractions;

namespace Cosine.Api.WebApi.Mapping;

/// <summary>
/// Domain entity → web DTO mapping, source-generated by Mapperly. The web-API analog of
/// <c>SongMapping</c>: every endpoint that returns a track/album/artist goes through here, so
/// no two endpoints can serve the same object with different fields.
/// <para>
/// Two invariants, both inherited from the Subsonic surface and both load-bearing:
/// (1) mapping always constructs a <b>fresh</b> DTO - the input entities come out of
/// <c>LibraryCache</c> and are shared across users and requests; (2) per-user fields
/// (<c>userRating</c>) are never written here - they are stamped afterwards by
/// <see cref="UserDataOverlay"/>, for the same reason.
/// </para>
/// </summary>
// RequiredMappingStrategy.Target: a DTO is deliberately narrower than its entity, so only
// unmapped *target* members are an error; unmapped source members are the whole point.
[Mapper(RequiredMappingStrategy = RequiredMappingStrategy.Target)]
public static partial class WebDtoMapper
{
    public static TrackDto ToDto(Track track)
    {
        var dto = MapTrack(track);

        // Refs come from the FK ids, which are always present, with the name from the
        // navigation when it happens to be loaded - same tolerance SongMapping has. The
        // generated nested mapping would NullReference on an unloaded navigation instead.
        dto.Artist = new ArtistRef(track.ArtistId, track.Artist?.Name ?? string.Empty);
        dto.Album = new AlbumRef(track.AlbumId, track.Album?.Name ?? string.Empty);

        // The credit fields come from the ordinal-sorted TrackArtists rows; a track scanned
        // before credits existed (or loaded without them) falls back to the primary artist,
        // which is exactly what SongMapping does on /rest.
        var credits = track.TrackArtists is { Count: > 0 }
            ? track.TrackArtists.OrderBy(ta => ta.Ordinal).ToList()
            : [];

        dto.DisplayArtist = ArtistCreditParsing.Display(
            credits.Select(c => (c.CreditedAs, c.JoinPhrase)).ToList(),
            track.Artist?.Name ?? string.Empty);

        dto.Artists = credits.Count > 0
            ? credits.Select(c => new ArtistRef(c.ArtistId, c.Artist?.Name ?? c.CreditedAs)).ToList()
            : dto.Artist is not null ? [dto.Artist] : [];

        // The recording id is the one MusicBrainz can actually look up; the release-track id
        // is only a fallback identity. Same preference as SongMapping.
        dto.MusicBrainzId = track.MusicBrainzRecordingId ?? track.MusicBrainzId;

        return dto;
    }

    [MapProperty(nameof(Track.AlbumId), nameof(TrackDto.ArtworkId))]
    [MapperIgnoreTarget(nameof(TrackDto.Artist))]
    [MapperIgnoreTarget(nameof(TrackDto.Album))]
    [MapperIgnoreTarget(nameof(TrackDto.MusicBrainzId))]
    [MapperIgnoreTarget(nameof(TrackDto.DisplayArtist))]
    [MapperIgnoreTarget(nameof(TrackDto.Artists))]
    [MapperIgnoreTarget(nameof(TrackDto.UserRating))]
    private static partial TrackDto MapTrack(Track track);

    [MapProperty(nameof(Album.Id), nameof(AlbumSummaryDto.ArtworkId))]
    [MapperIgnoreTarget(nameof(AlbumSummaryDto.UserRating))]
    public static partial AlbumSummaryDto ToSummaryDto(Album album);

    public static AlbumDetailDto ToDetailDto(Album album)
    {
        var dto = MapAlbumDetail(album);
        dto.Tracks = album.Tracks.Select(ToDto).ToList();
        return dto;
    }

    [MapProperty(nameof(Album.Id), nameof(AlbumDetailDto.ArtworkId))]
    [MapperIgnoreTarget(nameof(AlbumDetailDto.UserRating))]
    [MapperIgnoreTarget(nameof(AlbumDetailDto.Tracks))]
    private static partial AlbumDetailDto MapAlbumDetail(Album album);

    [MapProperty(nameof(Artist.Id), nameof(ArtistSummaryDto.ArtworkId))]
    [MapProperty("Albums.Count", nameof(ArtistSummaryDto.AlbumCount))]
    public static partial ArtistSummaryDto ToSummaryDto(Artist artist);

    public static ArtistDetailDto ToDetailDto(Artist artist)
    {
        var dto = MapArtistDetail(artist);
        dto.Albums = artist.Albums.Select(ToSummaryDto).ToList();
        return dto;
    }

    [MapProperty(nameof(Artist.Id), nameof(ArtistDetailDto.ArtworkId))]
    [MapProperty("Albums.Count", nameof(ArtistDetailDto.AlbumCount))]
    [MapperIgnoreTarget(nameof(ArtistDetailDto.Albums))]
    private static partial ArtistDetailDto MapArtistDetail(Artist artist);

    public static partial ArtistRef ToRef(Artist artist);

    public static partial AlbumRef ToRef(Album album);

    // Hand-written: Owner is a navigation that is not always loaded, and the entries pair
    // each PlaylistTrack's own id with its mapped track - no flat property copy involved.
    public static PlaylistSummaryDto ToSummaryDto(Playlist playlist)
        => FillPlaylist(new PlaylistSummaryDto(), playlist);

    public static PlaylistDetailDto ToDetailDto(Playlist playlist)
    {
        var dto = FillPlaylist(new PlaylistDetailDto(), playlist);
        dto.Entries = playlist.PlaylistTracks
            .OrderBy(pt => pt.Position)
            .Select(pt => new PlaylistEntryDto(pt.Id, ToDto(pt.Track)))
            .ToList();
        return dto;
    }

    private static T FillPlaylist<T>(T dto, Playlist p) where T : PlaylistSummaryDto
    {
        dto.Id = p.Id;
        dto.Name = p.Name;
        dto.Comment = p.Comment;
        dto.Owner = p.Owner?.Username;
        dto.IsPublic = p.IsPublic;
        dto.IsSystem = p.IsSystem;
        dto.TrackCount = p.TrackCount;
        dto.DurationMs = p.DurationMs;
        dto.CreatedAt = p.CreatedAt;
        return dto;
    }

    public static partial RadioStationDto ToDto(InternetRadioStation station);

    public static GenreDto ToDto(Core.Interfaces.GenreCount genre)
        => new(genre.Name, genre.SongCount, genre.AlbumCount);

    public static TranscodeFormatDto ToDto(Core.Interfaces.TranscodeFormat format)
        => new(format.Name, format.Extension, format.BitRates);
}
